            # the shared edge cells. The motif is oriented by position:
            # demos show the same asymmetric triangular 6-cell shape rotating
            # according to the original pixel's local arrangement is not enough;
            # use the observed cardinal-leaning motif for each occupied cell.
            for dr, dc in ((0, 2), (1, 0), (1, 1), (2, 0), (2, 1)):
                out[3*r+dr][3*c+dc] = v
